        Self {
            blocks: HashMap::new(),
            last_input_tokens: 0,
            last_cached_input_tokens: None,
            stop_reason: None,
            synthesizing_output,
            synthesized_tool_index: None,
            other_tool_fired: false,
            terminal_emitted: false,
            block_emitted: false,
            waiting_positions: Vec::new(),
