                    } else if let Some(BlockState::ToolUse {
                        call_id,
                        name,
                        name_emitted,
                    }) = self.blocks.get_mut(&index)
                    {
                        let (emit_name, call_id_out) = if *name_emitted {
                            (None, call_id.clone())
                        } else {
                            *name_emitted = true;
                            (Some(name.clone()), call_id.clone())
                        };
